\begin{equation*}
(D,E)=\chi(\underline{O}_D\overset{\mathbb L}{\otimes}\underline{O}_E)
=\chi(\underline{O}_D\otimes\underline{O}_E)
-\chi(\operatorname{Tor}^1(\underline{O}_D,\underline{O}_E)).
