\subsubsection*{Lemma 4.1.2.}
\underline{If the open set 4.1 is nonempty, then
$\operatorname{codim}_{\check{\mathbb P}^{r}}(F_1)\geq2$.}

\noindent\underline{Proof.}
By hypothesis,
\[
\dim R_1<\dim\mathbb P(N)=r-1,
\]
and $F_1=\varphi(R_1)$.

